from collections import defaultdict, deque
WINDOW, NEED = 10, 5              # minutes, denials
denials = defaultdict(deque)      # user -> recent denial times
armed = {}                        # user -> time the burst was seen

def on_event(t, user, action):
    if action == "mfa_push_denied":
        q = denials[user]
        q.append(t)
        while q and q[0] <= t - WINDOW:   # slide: drop old denials
            q.popleft()
        if len(q) >= NEED:
            armed[user] = t
    elif action == "mfa_push_approved" and user in armed:
        if t - armed[user] <= 15:
            return f"ALERT {user}: approved after {len(denials[user])} denials"
    return None
